from collections import Counter

def improved_transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for dr, dc in ((1, 1), (1, -1)):
        seen = set()
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg or (r, c) in seen:
                    continue
                pr, pc = r-dr, c-dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                run=[]; rr,cc=r,c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr,cc)); seen.add((rr,cc)); rr += dr; cc += dc
                if len(run) < 2:
                    continue
                for endpoint, sr, sc in ((run[0], -dr, -dc), (run[-1], dr, dc)):
                    er, ec = endpoint
                    attached = any(0 <= nr < h and 0 <= nc < w and grid[nr][nc] not in (bg, color)
                                  for nr in range(er-1, er+2) for nc in range(ec-1, ec+2)
                                  if (nr, nc) != endpoint)
                    if attached:
                        continue
                    rr, cc = er+sr, ec+sc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += sr; cc += sc
    return out

out2=improved_transform(grid)
